### acme/aidenhq fleet/briefs-skip-empty-days (3c4d5e6f7a8b)
diff --git a/services/paperclip-tasks-mcp/brief.mjs b/services/paperclip-tasks-mcp/brief.mjs
index 1a2b3c4..5d6e7f8 100644
--- a/services/paperclip-tasks-mcp/brief.mjs
+++ b/services/paperclip-tasks-mcp/brief.mjs
@@ -42,6 +42,8 @@ export function briefSections(items, { day }) {
   const sections = [];
   for (const [name, list] of groupByArea(items)) {
+    // A day with nothing in an area used to print an empty heading.
+    if (!list.length) continue;
     sections.push({ name, lines: list.map((i) => `- ${i.title} (${i.identifier})`) });
   }
   return sections;
diff --git a/services/paperclip-tasks-mcp/test/brief.test.mjs b/services/paperclip-tasks-mcp/test/brief.test.mjs
index 9a8b7c6..d5e4f3a 100644
--- a/services/paperclip-tasks-mcp/test/brief.test.mjs
+++ b/services/paperclip-tasks-mcp/test/brief.test.mjs
@@ -20,3 +20,9 @@ test("groups items by area", () => {
   assert.equal(briefSections(items, { day }).length, 2);
 });
+
+test("an area with no items prints no heading", () => {
+  const items = [{ title: "Ship it", identifier: "WOR-1", area: "eng" }];
+  const out = briefSections(items, { day, areas: ["eng", "ops"] });
+  assert.deepEqual(out.map((s) => s.name), ["eng"]);
+});
